#include <iostream>
#include <vector>
using namespace std;

void solve() {
  int N, H;
  cin >> N >> H;
  vector<int> T(N), L(N), U(N);
  for (int i = 0; i < N; i++) cin >> T[i] >> L[i] >> U[i];

  int t_prev = 0, l = H, u = H;
  for (int i = 0; i < N; i++) {
    int d = T[i] - t_prev;
    l -= d, u += d;
    t_prev = T[i];

    l = max(l, L[i]);
    u = min(u, U[i]);

    if (l > u) {
      cout << "No\n";
      return;
    }
  }
  cout << "Yes\n";
}

int main() {
  cin.tie(0)->sync_with_stdio(0);
  int T;
  cin >> T;
  while (T--) solve();
}
